    for key in ('Sources','Mapping','Approaches','Corners','Mouths','Depths'):g.socket(key,'NodeSocketGeometry')
    g.socket('Cell Size','NodeSocketFloat');g.socket('Input Valid','NodeSocketBool')
    g.socket('Valid','NodeSocketBool','OUTPUT');g.socket('Maximum Difference','NodeSocketFloat','OUTPUT')
